require "nokogiri"; doc = Nokogiri::XML(File.read("_site/sitemap.xml")); count = 0; err = false; doc.xpath("//xmlns:url", "xmlns" => "http://www.sitemaps.org/schemas/sitemap/0.9").each do |url| loc = url.xpath("xmlns:loc", "xmlns" => "http://www.sitemaps.org/schemas/sitemap/0.9").text; lastmod = url.xpath("xmlns:lastmod", "xmlns" => "http://www.sitemaps.org/schemas/sitemap/0.9").text; if lastmod.empty?; puts "Missing lastmod: #{loc}"; err = true; end; if loc.match?(/phase|plan|audit|report|draft|blueprint|map|roadmap/i); puts "Internal file found: #{loc}"; err = true; end; count += 1; end; puts "Total URLs: #{count}"; exit(err ? 1 : 0)
